import sys, json

class Solution:
    def kthSmallestPath(self, destination, k):
        v, h = destination
        result = []
        while v or h:
            if h:
                n = v + h - 1
                r = min(v, n - v)
                count = 1
                for i in range(1, r + 1):
                    count = count * (n - r + i) // i
                if k <= count:
                    result.append("H")
                    h -= 1
                    continue
                k -= count
            result.append("V")
            v -= 1
        return "".join(result)

