static long long choose_count(int n, int r) {
    if (r > n - r) r = n - r;
    long long result = 1;
    for (int i = 1; i <= r; ++i) {
        result = result * (n - r + i) / i;
    }
    return result;
}

char* kthSmallestPath(int* destination, int destinationSize, int k) {
    (void)destinationSize;

    int v = destination[0];
    int h = destination[1];
    long long rank = k;
    int len = v + h;

    char* result = (char*)malloc((size_t)len + 1);
    if (!result) return NULL;

    int pos = 0;
    while (v > 0 || h > 0) {
        if (h > 0) {
            long long count = choose_count(v + h - 1, v);
            if (rank <= count) {
                result[pos++] = 'H';
                --h;
                continue;
            }
            rank -= count;
        }
        result[pos++] = 'V';
        --v;
    }

    result[pos] = '\0';
    return result;
}

