import java.io.*;

class Solution {
    private long choose(int n, int r) {
        int k = Math.min(r, n - r);
        long result = 1;
        for (int i = 1; i <= k; i++) {
            result = result * (n - k + i) / i;
        }
        return result;
    }

    public String kthSmallestPath(int[] destination, int k) {
        int v = destination[0];
        int h = destination[1];
        long rank = k;
        StringBuilder result = new StringBuilder(v + h);

        while (v > 0 || h > 0) {
            if (h > 0) {
                long count = choose(v + h - 1, v);
                if (rank <= count) {
                    result.append('H');
                    h--;
                    continue;
                }
                rank -= count;
            }
            result.append('V');
            v--;
        }
        return result.toString();
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        String nums = line.replaceAll("[^0-9]+", " ").trim();
        String[] parts = nums.split("\\s+");
        int row = Integer.parseInt(parts[0]);
        int column = Integer.parseInt(parts[1]);
        int k = Integer.parseInt(parts[2]);

        String result = new Solution().kthSmallestPath(new int[]{row, column}, k);
        System.out.println("\"" + result + "\"");
    }
}

